-- The Glass Menagerie
UPDATE projects SET seoKeywords = 'scenic design, The Glass Menagerie, Tennessee Williams, Maples Repertory Theatre, memory play' WHERE slug = 'the-glass-menagerie';

INSERT IGNORE INTO tags (name) VALUES 
('Tennessee Williams'), ('Memory Play'), ('Southern Gothic'), ('1930s'), ('Maples Repertory'), ('Regional Theatre'), ('2025'), ('2024'), ('Realistic Interior'), ('Unit Set');

INSERT IGNORE INTO projectTags (projectId, tagId)
SELECT p.id, t.id FROM projects p, tags t 
WHERE p.slug = 'the-glass-menagerie' AND t.name IN ('Tennessee Williams', 'Memory Play', 'Southern Gothic', '1930s', 'Regional Theatre', '2025');

